          'text-font': findFonts(map),
          'text-size': 12,
          'text-field': '▲',
          'text-allow-overlap': true,
          'text-rotate': ['get', 'rotation'],
        },
        on: {
          mouseenter: onMouseEnter,
          mouseleave: onMouseLeave,
